import{_ as r,o as e,c as a,ag as o}from"./chunks/framework.BjY7aUvS.js";const u=JSON.parse('{"title":"延伸工具站导航 · 官方优先，境外补充","description":"家庭实用工具站合集：辟谣平台/科普中国/天气网等官方阵营 + MuscleWiki 等境外工具站（显式例外收录），每条注明与官方内容的配对。","frontmatter":{"title":"延伸工具站导航 · 官方优先，境外补充","issuer":"混合来源（官方平台 + 境外工具站，见 ADR 0019）","source_tier":"混合（官方 + 显式例外）","version":"—","published":"—","source_url":"https://www.piyao.org.cn/","status":"现行服务","tags":["工具站","健身","营养","辟谣","实用网站"],"type":"查询页","reviewed":false,"description":"家庭实用工具站合集：辟谣平台/科普中国/天气网等官方阵营 + MuscleWiki 等境外工具站（显式例外收录），每条注明与官方内容的配对。"},"headers":[],"relativePath":"query/daily-tools.md","filePath":"query/daily-tools.md"}'),d={name:"query/daily-tools.md"};function n(s,t,l,i,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="延伸工具站导航-·-官方优先-境外补充" tabindex="-1">延伸工具站导航 · 官方优先，境外补充 <a class="header-anchor" href="#延伸工具站导航-·-官方优先-境外补充" aria-label="Permalink to &quot;延伸工具站导航 · 官方优先，境外补充&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">收录说明</p><p>本页包含<strong>两类</strong>工具站：<strong>官方阵营</strong>（白名单内，一级来源）与<strong>境外/市场化延伸</strong>（<a href="/SageRelay/project/adr/0019-tool-sites.html">ADR 0019</a> 显式例外：免费核心、无佣金无利益关联、非官方背书、可随时下架）。境外工具的数据标准（如美国 USDA）<strong>不等于中国官方推荐量</strong>，膳食与运动决策以本站官方内容为准。</p></div><h2 id="官方阵营-一级来源" tabindex="-1">官方阵营（一级来源） <a class="header-anchor" href="#官方阵营-一级来源" aria-label="Permalink to &quot;官方阵营（一级来源）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具站</th><th>查什么</th><th>入口</th></tr></thead><tbody><tr><td><strong>中国互联网联合辟谣平台</strong>（网信办）</td><td>谣言查证——家庭群里转来的&quot;震惊体&quot;先来这查</td><td><a href="https://www.piyao.org.cn/" target="_blank" rel="noreferrer">piyao.org.cn</a>（已核验）</td></tr><tr><td><strong>科普中国</strong>（中国科协）</td><td>权威科普内容库（健康、食品安全、应急等）</td><td><a href="https://www.kepuchina.cn/" target="_blank" rel="noreferrer">kepuchina.cn</a>（已核验）</td></tr><tr><td><strong>中国天气网</strong>（中国气象局）</td><td>官方天气预报与预警（比商业 App 少广告）</td><td><a href="https://www.weather.com.cn/" target="_blank" rel="noreferrer">weather.com.cn</a>（已核验）</td></tr><tr><td><strong>国家智慧教育公共服务平台</strong>（教育部）</td><td><strong>免费</strong>中小学课程资源、职业教育、老年教育</td><td><a href="https://www.smartedu.cn/" target="_blank" rel="noreferrer">smartedu.cn</a>（已核验）</td></tr><tr><td><strong>国家图书馆</strong></td><td>读者注册后免费使用数字图书、期刊、古籍资源</td><td><a href="https://www.nlc.cn/" target="_blank" rel="noreferrer">nlc.cn</a>（已核验）</td></tr></tbody></table><h2 id="延伸阵营-境外工具站-·-adr-0019-例外" tabindex="-1">延伸阵营（境外工具站 · ADR 0019 例外） <a class="header-anchor" href="#延伸阵营-境外工具站-·-adr-0019-例外" aria-label="Permalink to &quot;延伸阵营（境外工具站 · ADR 0019 例外）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具站</th><th>查什么</th><th>入口与提示</th></tr></thead><tbody><tr><td><strong>MuscleWiki</strong></td><td>按肌群点选 → 对应训练动作视频（中文界面），健身&quot;看图点菜&quot;</td><td><a href="https://musclewiki.com/" target="_blank" rel="noreferrer">musclewiki.com</a>（已核验，境外加载稍慢）</td></tr><tr><td><strong>USDA FoodData Central</strong></td><td>美国农业部食物营养数据库——查某种食物的热量/营养素明细</td><td><a href="https://fdc.nal.usda.gov/" target="_blank" rel="noreferrer">fdc.nal.usda.gov</a>（境外站点加载较慢，英文）</td></tr><tr><td><strong>NutritionFacts.org</strong></td><td>非营利营养研究科普（按食物/健康话题检索文献综述）</td><td><a href="https://nutritionfacts.org/" target="_blank" rel="noreferrer">nutritionfacts.org</a>（境外较慢，英文）</td></tr></tbody></table><p><strong>配对使用原则</strong>（官方优先）：</p><ul><li>练什么、练多少 → 以<a href="/SageRelay/data/physical-activity-2021.html">身体活动指南推荐量</a>和<a href="/SageRelay/query/fitness-map.html">健身一张图</a>为准；<strong>具体动作怎么标准地做</strong> → MuscleWiki 补细节。</li><li>吃多少、怎么搭配 → 以<a href="/SageRelay/guides/dietary-guidelines-2022.html">膳食指南</a>和对应<a href="/SageRelay/guides/hypertension-2023.html">食养指南</a>为准；<strong>某种食物的营养细节</strong> → USDA 数据库补查询（美国数据，参考用）。</li><li>补剂、某种食物的&quot;功效&quot;传言 → 先查<a href="https://www.piyao.org.cn/" target="_blank" rel="noreferrer">辟谣平台</a>，再看 nutritionfacts 的文献综述。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>健身设施：<a href="/SageRelay/query/fitness-map.html">健身一张图</a> · 饮食总纲：<a href="/SageRelay/guides/dietary-guidelines-2022.html">膳食指南</a> · 谣言治理：<a href="/SageRelay/query/complaint-channels.html">投诉渠道全景</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>官方阵营</td><td>网信办、中国科协、中国气象局、教育部、国家图书馆（一级来源，均已核验）</td></tr><tr><td>延伸阵营</td><td>MuscleWiki、USDA、NutritionFacts.org——ADR 0019 显式例外，无佣金无利益关联</td></tr></tbody></table>',12)])])}const f=r(d,[["render",n]]);export{u as __pageData,f as default};
